$error='';$notice=isset($_GET['admin_reset'])?'Administrator password reset. Sign in with the new password.':''; if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$email=strtolower(trim($_POST['email']??''));$limit=rate_limit_page_message($pdo,'login-ip',rate_limit_ip_subject(),12,900)?:rate_limit_page_message($pdo,'login-account',rate_limit_subject($email),8,900);if($limit){$error=$limit;}else{$s=$pdo->prepare('SELECT id,password_hash FROM users WHERE email=? AND status="active"');$s->execute([$email]);$u=$s->fetch();if($u&&$u['password_hash']&&password_verify($_POST['password']??'',$u['password_hash'])){if(password_needs_rehash((string)$u['password_hash'],PASSWORD_DEFAULT)){$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash((string)($_POST['password']??''),PASSWORD_DEFAULT),$u['id']]);}session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['rotated_at']=time();$_SESSION['last_activity']=time();$_SESSION['auth_time']=time();header('Location:'.post_auth_destination($pdo,(int)$u['id']));exit;}$error='Invalid email or password.';}}
